WITH agg AS ( SELECT cc.cc_state AS state, cc.cc_city AS city, COUNT(DISTINCT cc.cc_call_center_id) AS call_center_cnt, SUM(inv.inv_quantity_on_hand) AS total_inventory_qty, AVG(cc.cc_tax_percentage) AS avg_cc_tax_pct, AVG(ws.web_tax_percentage) AS avg_ws_tax_pct, COUNT(DISTINCT c.c_customer_id) AS distinct_customers, MIN(c.c_birth_year) AS min_birth_year, MAX(c.c_birth_year) AS max_birth_year, (SUM(inv.inv_quantity_on_hand) / NULLIF(COUNT(DISTINCT cc.cc_call_center_id), 0)) AS avg_inventory_per_center FROM call_center cc JOIN inventory inv ON cc.cc_open_date_sk = inv.inv_date_sk JOIN web_site ws ON cc.cc_state = ws.web_state AND cc.cc_city = ws.web_city JOIN customer c ON cc.cc_manager = c.c_login WHERE cc.cc_tax_percentage >= 0.05 AND cc.cc_rec_end_date > DATE '2000-12-31' AND ws.web_gmt_offset BETWEEN -5 AND 5 AND c.c_birth_year BETWEEN 1970 AND 1990 GROUP BY cc.cc_state, cc.cc_city HAVING COUNT(DISTINCT cc.cc_call_center_id) >= 1 ) SELECT state, city, call_center_cnt, total_inventory_qty, avg_cc_tax_pct, avg_ws_tax_pct, distinct_customers, min_birth_year, max_birth_year, avg_inventory_per_center, RANK() OVER (ORDER BY total_inventory_qty DESC) AS inventory_rank FROM agg ORDER BY total_inventory_qty DESC LIMIT 100
